data: {"index":1,"delta":{"text":"# Kyoto: A Journey Through the Heart","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" of Old Japan\n\nKyoto is a city where time seems to fold in on itself. As the imperial capital of Japan","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" for over a millennium, it remains the country’s cultural and spiritual epicenter. Unlike Tokyo, which looks toward the future","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":", Kyoto preserves the elegance of the past, offering a landscape of shimmering golden pavilions, silent Zen gardens, and the mysterious","type":"text"},"event_type":"step.delta"}

event: step.delta
