data: {"index":1,"delta":{"text":" maple leaves turn brilliant shades of crimson and gold. Temples like Eikan-do and Tofuku-ji become","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" focal points for \"leaf hunting.\"\n*   **Summer (July):** While humid, July hosts the Gion","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" Matsuri, one of Japan’s most famous festivals, featuring massive floats and vibrant street processions.\n*   **","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"Winter (January to February):** A quieter time. Seeing the Golden Pavilion dusted in white snow is a rare and ethereal","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" sight.\n\n## Must-Visit Districts and Landmarks\n\n### Eastern Kyoto (Higashiyama)\nThis area is the","type":"text"},"event_type":"step.delta"}

